import React from 'react';

const Navbar = ({ username, balance, onLogout }) => {
    return (
        <nav style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: '12px 24px',
            background: '#141b2b',
            borderBottom: '1px solid #2a3a5c',
            position: 'sticky',
            top: 0,
            zIndex: 100
        }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <h2 style={{ color: '#4CAF50', margin: 0 }}>📈 DemoTrader</h2>
                <span style={{
                    fontSize: '11px',
                    background: '#1a2332',
                    padding: '2px 8px',
                    borderRadius: '10px',
                    color: '#8a9bb5'
                }}>DEMO</span>
            </div>
            
            <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <span style={{ color: '#8a9bb5' }}>👤</span>
                    <span>{username}</span>
                </div>
                <div style={{
                    background: '#1a2332',
                    padding: '6px 16px',
                    borderRadius: '6px',
                    border: '1px solid #2a3a5c',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '8px'
                }}>
                    <span>💰</span>
                    <span style={{ fontWeight: 'bold' }}>₹{balance.toFixed(2)}</span>
                </div>
                <button
                    onClick={onLogout}
                    style={{
                        padding: '6px 16px',
                        background: '#dc3545',
                        color: 'white',
                        border: 'none',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontSize: '14px'
                    }}
                >
                    Logout
                </button>
            </div>
        </nav>
    );
};

export default Navbar;
